{
  "name": "@luxass/opencode-voice",
  "version": "0.2.0",
  "description": "Native microphone capture and transcription for the OpenCode terminal",
  "keywords": [
    "dictation",
    "opencode",
    "opencode-plugin",
    "speech-to-text",
    "transcription",
    "voice"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/luxass/agent-extensions",
    "directory": "packages/opencode-voice"
  },
  "files": [
    "src",
    "README.md",
    "LICENSE"
  ],
  "type": "module",
  "exports": {
    ".": "./src/index.ts",
    "./tui": "./src/tui.ts"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@luxass/agent-voice": "0.5.1",
    "@opencode/plugin": "2.1.1",
    "@opentui/solid": "0.6.6",
    "typebox": "1.3.34"
  },
  "engines": {
    "node": ">=24"
  },
  "scripts": {
    "lint": "oxlint .",
    "lint:fix": "oxlint --fix .",
    "fmt": "oxfmt .",
    "fmt:check": "oxfmt --check .",
    "typecheck": "tsc -p tsconfig.json"
  }
}
